import{_ as e,o as d,c as r,a2 as i}from"./chunks/framework.BS0bAV7E.js";const h=JSON.parse('{"title":"L1 指南：tui_ext.h——用模块搭建界面","description":"","frontmatter":{},"headers":[],"relativePath":"zh/l1/tui-ext.md","filePath":"zh/l1/tui-ext.md"}'),o={name:"zh/l1/tui-ext.md"};function a(c,t,_,n,s,u){return d(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="l1-指南-tui-ext-h——用模块搭建界面" tabindex="-1">L1 指南：tui_ext.h——用模块搭建界面 <a class="header-anchor" href="#l1-指南-tui-ext-h——用模块搭建界面" aria-label="Permalink to &quot;L1 指南：tui_ext.h——用模块搭建界面&quot;">​</a></h1><p><code>tui/tui_ext.h</code> 是 TUI 扩展接口面——包含七个注册表中的 37 个声明。所有表都是静态的（独立的内核，无 malloc 依赖）；注册成功返回 0，表满返回 -1，重复名称/键返回 -2。每个条目都携带其所有者（内核内置页面为 &quot;builtin&quot;），因此注销功能可用。</p><h2 id="七个注册表" tabindex="-1">七个注册表 <a class="header-anchor" href="#七个注册表" aria-label="Permalink to &quot;七个注册表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>注册表</th><th>API</th><th>功能</th></tr></thead><tbody><tr><td>7.1 菜单</td><td><code>tui_menu_register/unregister/list/sort</code></td><td>启动器条目：标签、描述、ASCII 图标 <code>[T]</code>、组、热键、优先级、动作回调</td></tr><tr><td>7.2 页面</td><td><code>tui_page_register/unregister/list/render/input</code> + <code>tui_ext_page_main</code></td><td>完整页面：render(win, scroll) + input(key) -&gt; 1 已消耗；<code>tui_ext_page_main</code> 是通用运行器</td></tr><tr><td>7.3 组件</td><td><code>tui_widget_register/unregister/list/render/event</code></td><td>可重用组件类型</td></tr><tr><td>7.4 命令</td><td><code>tui_cmd_register/unregister/list/execute</code></td><td>TUI 命令行钩子；<code>tui_cmd_execute</code> 返回函数的返回码或 -3 无命令</td></tr><tr><td>7.5 主题</td><td><code>tui_theme_register/unregister/list/set</code></td><td>颜色主题</td></tr><tr><td>7.6 热键</td><td><code>tui_key_register/unregister/list/conflict</code></td><td>全局热键（内置冲突检测）</td></tr><tr><td>7.7 事件</td><td><code>tui_event_register/unregister/list/dispatch</code></td><td>通用事件订阅者</td></tr></tbody></table><p>限制是命名常量（<code>TUI_EXT_MENU_MAX 24</code>、<code>TUI_EXT_NAME_MAX 40</code> 等）——有界表，拒绝时明确提示，永不截断。</p><h2 id="有效模式" tabindex="-1">有效模式 <a class="header-anchor" href="#有效模式" aria-label="Permalink to &quot;有效模式&quot;">​</a></h2><p>在模块初始化时注册；在拆除时注销；所有者标签使跨模块重注册具有幂等性。中文 TUI 应用（<code>tui_cn_hw/net/sysinfo</code>）和 TUI 命令桥是树内两个参考实现——编写自己的前先阅读其中一个。</p><h2 id="渲染" tabindex="-1">渲染 <a class="header-anchor" href="#渲染" aria-label="Permalink to &quot;渲染&quot;">​</a></h2><p>页面通过与桌面（<code>tui_win</code> 窗口）相同的帧缓冲基元进行渲染；<code>tui_page_render</code> 接收窗口和滚动偏移量。输入：页面消耗按键时返回 1，否则返回 0 以便继续传递。</p>',9)])])}const p=e(o,[["render",a]]);export{h as __pageData,p as default};
